/* @autogenerated */
import type { Token, Tokens } from 'marked';
import { Align, Block, Run } from './document.model';

/** Marca de salto de página en la plantilla: `<!-- pagebreak -->` en su propia línea. */
const PAGE_BREAK = /^<!--\s*pagebreak\s*-->\s*$/i;

type Style = Omit<Run, 'text' | 'break'>;

/** Markdown (ya rellenado) a bloques del documento. */
export async function markdownBlocks(markdown: string): Promise<Block[]> {
  const { Lexer } = await import('marked');
  return blocks(new Lexer().lex(markdown));
}

/** Tokens de bloque de `marked` a bloques; lo que ningún formato sabe escribir se descarta. */
export function blocks(tokens: Token[]): Block[] {
  const out: Block[] = [];
  tokens.forEach((token) => {
    switch (token.type) {
      case 'heading': {
        const heading = token as Tokens.Heading;
        out.push({ kind: 'heading', level: heading.depth, runs: runs(heading.tokens) });
        break;
      }
      case 'paragraph':
        out.push({ kind: 'paragraph', runs: runs((token as Tokens.Paragraph).tokens) });
        break;
      case 'text': {
        // Texto suelto (p. ej. en listas compactas)
        const text = token as Tokens.Text;
        out.push({ kind: 'paragraph', runs: text.tokens ? runs(text.tokens) : [{ text: text.text }] });
        break;
      }
      case 'list': {
        const list = token as Tokens.List;
        out.push({
          kind: 'list',
          ordered: list.ordered,
          start: typeof list.start === 'number' ? list.start : 1,
          items: list.items.map((item) => blocks(item.tokens)),
        });
        break;
      }
      case 'table': {
        const table = token as Tokens.Table;
        out.push({
          kind: 'table',
          header: table.header.map((cell) => runs(cell.tokens)),
          rows: table.rows.map((row) => row.map((cell) => runs(cell.tokens))),
          align: table.align as Align[],
        });
        break;
      }
      case 'code':
        out.push({ kind: 'code', text: (token as Tokens.Code).text });
        break;
      case 'blockquote':
        out.push({ kind: 'quote', blocks: blocks((token as Tokens.Blockquote).tokens) });
        break;
      case 'hr':
        out.push({ kind: 'rule' });
        break;
      case 'html':
        if (PAGE_BREAK.test((token as Tokens.HTML).text.trim())) {
          out.push({ kind: 'pagebreak' });
        }
        break;
      default:
        // space, def… no producen contenido
        break;
    }
  });
  return out;
}

/** Tokens en línea a trozos de texto con formato, acumulando el estilo de los anidados. */
export function runs(tokens: Token[] | undefined, style: Style = {}): Run[] {
  const out: Run[] = [];
  (tokens ?? []).forEach((token) => {
    switch (token.type) {
      case 'strong':
        out.push(...runs((token as Tokens.Strong).tokens, { ...style, bold: true }));
        break;
      case 'em':
        out.push(...runs((token as Tokens.Em).tokens, { ...style, italic: true }));
        break;
      case 'del':
        out.push(...runs((token as Tokens.Del).tokens, { ...style, strike: true }));
        break;
      case 'codespan':
        out.push({ ...style, code: true, text: decode((token as Tokens.Codespan).text) });
        break;
      case 'link': {
        const link = token as Tokens.Link;
        out.push(...runs(link.tokens, { ...style, link: link.href }));
        break;
      }
      case 'br':
        out.push({ ...style, text: '', break: true });
        break;
      case 'text': {
        const text = token as Tokens.Text;
        if (text.tokens?.length) {
          out.push(...runs(text.tokens, style));
        } else {
          out.push({ ...style, text: decode(text.text) });
        }
        break;
      }
      case 'escape':
        out.push({ ...style, text: decode((token as Tokens.Escape).text) });
        break;
      default:
        if ('text' in token && typeof token.text === 'string') {
          out.push({ ...style, text: decode(token.text) });
        }
        break;
    }
  });
  return out;
}

/** `marked` deja las entidades HTML de los textos sin decodificar. */
function decode(text: string): string {
  return text
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&');
}
